"""Templates versionados junto à aplicação; autoescape permanece ativo."""
TEMPLATES = {
'base.html': '''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Eldi — Vínculos</title><style>body{font:16px/1.5 system-ui;margin:0;background:#f4f7f6;color:#18362d}header,main{padding:24px;max-width:1100px;margin:auto}header{display:flex;justify-content:space-between;border-bottom:1px solid #abc1b7}a{color:#145740}button,.button{display:inline-block;background:#145740;color:white;padding:12px 18px;border:0;border-radius:5px;min-height:44px;box-sizing:border-box;text-decoration:none}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #a26000;outline-offset:3px}nav{display:flex;gap:18px;align-items:center;flex-wrap:wrap}.panel{background:white;padding:24px;border:1px solid #c4d4cd;border-radius:8px;margin:20px 0}label{display:block;font-weight:bold}input,select,textarea{font:inherit;min-height:44px;padding:8px;max-width:100%;box-sizing:border-box}input[type=text],textarea{width:100%}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #c4d4cd}.table{overflow:auto}.errorlist{color:#8c2017}.msg{padding:14px;border:1px solid #638b70;background:#eaf4eb}small{display:block}form p{margin:18px 0}.muted{color:#486157}.skip{position:absolute;top:-100px}.skip:focus{top:0;background:white}ul{padding-left:20px}</style><a href="#conteudo" class="skip">Pular para conteúdo</a><header><strong>ELDI · Vínculos de fornecedores</strong><span>{{user.username}}</span></header><main id="conteudo"><nav><a href="{% url 'home' %}">Menu inicial</a><a href="{% url 'pending' %}">Consultar pendências</a>{% if perms.eldi.add_importacao %}<a href="{% url 'upload' %}">Importar CSV</a>{% endif %}{% if user.is_authenticated %}<form action="{% url 'logout' %}" method="post">{% csrf_token %}<button>Sair</button></form>{% endif %}</nav>{% for message in messages %}<p role="status" class="msg">{{message}}</p>{% endfor %}{% block content %}{% endblock %}<p class="muted">Informações conforme arquivos importados. Correções cadastrais são feitas no Consinco.</p></main></html>''',
'login.html': '''{% extends 'base.html' %}{% block content %}<h1>Entrar</h1><section class="panel"><form method="post">{% csrf_token %}{{form.as_p}}<button>Entrar</button></form></section>{% endblock %}''',
'home.html': '''{% extends 'base.html' %}{% block content %}<h1>Acompanhamento de vínculos</h1><p>Identifique cadastros incompletos e organize a conferência.</p><div class="panel"><h2>Consultar pendências</h2><p>Busque produtos e registre responsáveis, observações e andamento.</p><a class="button" href="{% url 'pending' %}">Consultar pendências</a></div>{% if pode_importar %}<div class="panel"><h2>Nova referência de dados</h2><p>Importe um CSV padronizado por loja para conferir vínculos.</p><a class="button" href="{% url 'upload' %}">Importar arquivo</a></div>{% endif %}{% endblock %}''',
'pending.html': '''{% extends 'base.html' %}{% block content %}<h1>Pendências de fornecedores</h1><form method="get" class="panel"><label for="q">Código ou descrição</label><input id="q" name="q" value="{{q}}" maxlength="200"><label for="loja">Loja</label><select id="loja" name="loja"><option value="">Todas</option>{% for l in lojas %}<option value="{{l.pk}}" {% if request.GET.loja == l.pk|stringformat:'s' %}selected{% endif %}>{{l}}</option>{% endfor %}</select><label for="situacao">Situação</label><select id="situacao" name="situacao"><option value="">Todas</option>{% for k,v in estados %}<option value="{{k}}" {% if request.GET.situacao == k %}selected{% endif %}>{{v}}</option>{% endfor %}</select><button>Pesquisar</button> <a href="{% url 'pending' %}">Limpar filtros</a></form><div class="table panel"><table><caption>Produtos em acompanhamento · {{page.paginator.count}} registro(s)</caption><tr><th scope="col">Produto</th><th scope="col">Loja</th><th scope="col">Situação</th><th scope="col">Responsável</th><th scope="col">Verificação</th><th scope="col">Ação</th></tr>{% for p in page %}<tr><td>{{p.produto.codigo}}<small>{{p.produto.descricao}}</small></td><td>{{p.loja.codigo}}</td><td>{{p.get_situacao_display}}</td><td>{{p.responsavel.username|default:'Sem responsável'}}</td><td>{{p.ultima_importacao.referencia}}{% if p.nao_verificado %}<small>Não verificado na última importação</small>{% endif %}</td><td><a class="button" href="{% url 'update' p.pk %}">Acompanhar</a></td></tr>{% empty %}<tr><td colspan="6">Nenhum registro encontrado.</td></tr>{% endfor %}</table></div><p>Página {{page.number}} de {{page.paginator.num_pages}}</p>{% if page.has_next %}<a href="?q={{q|urlencode}}&loja={{request.GET.loja|urlencode}}&situacao={{request.GET.situacao|urlencode}}&page={{page.next_page_number}}">Próxima página</a>{% endif %}{% if page.has_previous %}<a href="?q={{q|urlencode}}&loja={{request.GET.loja|urlencode}}&situacao={{request.GET.situacao|urlencode}}&page={{page.previous_page_number}}">Página anterior</a>{% endif %}{% endblock %}''',
'update.html': '''{% extends 'base.html' %}{% block content %}<h1>{{p.produto.codigo}} — {{p.produto.descricao}}</h1><p>{{p.loja}} · {{p.get_situacao_display}}</p>{% if bloqueada %}<p class="msg">Regularização confirmada. Reabertura depende de nova importação.</p>{% else %}<form class="panel" method="post">{% csrf_token %}{{form.as_p}}<p>Regularização informada aguarda confirmação em dados posteriores.</p><button>Salvar atualização</button> <a href="{% url 'pending' %}">Cancelar</a></form>{% endif %}<h2>Histórico</h2><ul>{% for e in p.historico.all %}<li>{{e.ocorrido_em}} · {{e.usuario.username}} · {{e.nova}}<p>{{e.descricao}}</p></li>{% endfor %}</ul>{% endblock %}''',
'upload.html': '''{% extends 'base.html' %}{% block content %}<h1>Importar e conferir CSV</h1><p>UTF-8, até 10 MB e 50 mil linhas. Cabeçalhos: produto_codigo,produto_descricao,fornecedor_codigo,fornecedor_nome. Produto sem fornecedor deve estar presente com os dois campos de fornecedor vazios.</p><form class="panel" method="post" enctype="multipart/form-data">{% csrf_token %}{{form.as_p}}<button>Validar e importar</button></form>{% if result %}<section class="panel" role="status"><h2>Conferência concluída</h2><p>{{result.loja}} · {{result.referencia}} · {{result.arquivo}}</p><p>{{result.itens.count}} produto(s) presente(s). Consulte a lista para verificar situações e histórico.</p><a class="button" href="{% url 'pending' %}">Consultar pendências</a></section>{% endif %}<p>Arquivo rejeitado não altera produtos ou pendências; a tentativa fica registrada. Produto ausente mantém a situação anterior.</p>{% endblock %}'''
}
